export const NBU95_CONTROLS: Nbu95ControlSeed[] = [
  { controlCode: 'NBU95-1', title: 'Це Положення розроблено відповідно до Законів України “Про Національний банк України”, “Про банки і банківську діяльність”, “Про захист інформації в інформац...', description: 'Це Положення розроблено відповідно до Законів України “Про Національний банк України”, “Про банки і банківську діяльність”, “Про захист інформації в інформаційно-телекомунікаційних системах”, “Про основи національної безпеки України”, указів Президента України від 13 лютого 2017 року № 32/2017 “Про рішення Ради національної безпеки і оборони України від 29 грудня 2016 року “Про загрози кібербезпеці держави та невідкладні заходи з їх нейтралізації” та від 15 березня 2016 року № 96/2016 “Про рішення Ради національної безпеки і оборони України від 27 січня 2016 року “Про Стратегію кібербезпеки України”, національних стандартів України з питань інформаційної безпеки ДСТУ ISO/IEC 27000:2015 “Інформаційні технології. Методи захисту. Система управління інформаційною безпекою. Огляд і словник” (далі – ДСТУ ISO/IEC 27000:2015), ДСТУ ISO/IEC 27001:2015 “Інформаційні технології. Методи захисту. Системи управління інформаційною безпекою. Вимоги” (далі – ДСТУ ISO/IEC 27001:2015), ДСТУ ISO/IEC 27002:2015 “Інформаційні технології. Методи захисту. Звід практик щодо заходів інформаційної безпеки” (далі – ДСТУ ISO/IEC 27002:2015), які прийняті наказом Державного підприємства “Український науково-дослідний і навчальний центр проблем стандартизації, сертифікації та якості” від 18 грудня 2015 року № 193, та з урахуванням міжнародних стандартів з питань інформаційної безпеки, загальноприйнятих у міжнародній практиці принципів забезпечення інформаційної безпеки і кіберзахисту з метою підвищення рівня інформаційної безпеки в банківській системі України.', category: 'I. General Provisions', source: 'NBU Resolution №95 п. 1' },
  { controlCode: 'NBU95-2', title: 'Це Положення встановлює: 1) обов’язкові мінімальні вимоги щодо організації заходів із забезпечення інформаційної безпеки та кіберзахисту; 2) принципи управлі...', description: 'Це Положення встановлює: 1) обов’язкові мінімальні вимоги щодо організації заходів із забезпечення інформаційної безпеки та кіберзахисту; 2) принципи управління інформаційною безпекою; 3) вимоги до інформаційних систем банку, що взаємодіють з інформаційними системами Національного банку України (далі – Національний банк), з урахуванням напрямів розвитку криптографічного захисту інформації в інформаційних системах Національного банку.', category: 'I. General Provisions', source: 'NBU Resolution №95 п. 2' },
  { controlCode: 'NBU95-3', title: 'У цьому Положенні терміни та поняття вживаються в таких значеннях: 1) багатофакторна автентифікація – автентифікація, яка здійснюється за допомогою захищених...', description: 'У цьому Положенні терміни та поняття вживаються в таких значеннях: 1) багатофакторна автентифікація – автентифікація, яка здійснюється за допомогою захищених механізмів двох або більше типів [наприклад, застосування для автентифікації пароля разом із апаратним засобом захисту інформації (токеном) або біометричної автентифікації разом із паролем]; 2) зловмисний код – комп’ютерна програма/комплекс комп’ютерних програм або частина програмного коду інформаційної системи, що впроваджується за участю користувача або виконується автоматично, створює загрозу або умови для реалізації загрози порушення штатної роботи обладнання банку та/або порушення конфіденційності, цілісності, доступності інформації, яка обробляється в інформаційних системах банку; 3) критичні бізнес-процеси банку – бізнес-процеси діяльності банку, визначені банком критичними щодо інформаційної безпеки за результатом їх оцінювання банком за такими критеріями: конфіденційність, цілісність, доступність; 4) мережа банку – комплекс технічних засобів телекомунікацій, призначених для маршрутизації, комутації, передавання та/або приймання інформації дротовим та/або бездротовим зв’язком між кінцевим обладнанням (комп’ютерне обладнання, інші компоненти інформаційних систем банку) усередині периметра банку; 5) мінімальний рівень повноважень – повноваження та права доступу, мінімально необхідні для якісного виконання персоналом банку службових обов’язків; 6) пристрої уніфікованого управління загрозами (Unified threat management, UTM) – пристрої, які можуть виконувати кілька функцій безпеки з одного пристрою: міжмережевий екран, запобігання несанкціонованого доступу до мережі, антивірусний шлюз, антиспамовий шлюз, віртуальна приватна мережа (Virtual private network, VPN), фільтрація вмісту, балансування навантаження, запобігання витоку даних; 7) ризик-орієнтований підхід до забезпечення інформаційної безпеки – прийняття управлінських рішень на підставі аналізу порівняння поточних ризиків інформаційної безпеки з прийнятними. Інші терміни, що вживаються в цьому Положенні, використовуються в значеннях, визначених законами України, нормативно-правовими актами Національного банку та ДСТУ ISO/IEC 27000:2015.', category: 'I. General Provisions', source: 'NBU Resolution №95 п. 3' },
  { controlCode: 'NBU95-4', title: 'Це Положення не встановлює вимог щодо: 1) фізичної безпеки приміщень банків, технічного захисту інформації для приміщень банків, використання криптографічних...', description: 'Це Положення не встановлює вимог щодо: 1) фізичної безпеки приміщень банків, технічного захисту інформації для приміщень банків, використання криптографічних засобів захисту інформації Національного банку в інформаційних системах Національного банку, вимоги до яких визначені відповідними нормативно-правовими актами Національного банку; 2) використання хмарних технологій/сервісів (Сloud technologies) у сфері автоматизації, технічної й технологічної підтримки діяльності банків, вимоги до яких визначаються окремим документом.', category: 'I. General Provisions', source: 'NBU Resolution №95 п. 4' },
  { controlCode: 'NBU95-5', title: '4. Це Положення не встановлює вимог щодо: 1) фізичної безпеки приміщень банків, технічного захисту інформації для приміщень банків, використання криптографіч...', description: '4. Це Положення не встановлює вимог щодо: 1) фізичної безпеки приміщень банків, технічного захисту інформації для приміщень банків, використання криптографічних засобів захисту інформації Національного банку в інформаційних системах Національного банку, вимоги до яких визначені відповідними нормативно-правовими актами Національного банку; 2) використання хмарних технологій/сервісів (Сloud technologies) у сфері автоматизації, технічної й технологічної підтримки діяльності банків, вимоги до яких визначаються окремим документом. 5. Вимоги цього Положення поширюються на банки. Вимоги розділу ІІІ цього Положення також поширюються на небанківські установи – учасників інформаційних систем Національного банку.', category: 'I. General Provisions', source: 'NBU Resolution №95 п. 5' },
  { controlCode: 'NBU95-6', title: 'Принципи забезпечення інформаційної безпеки: 1) підхід до забезпечення інформаційної безпеки має бути системним (комплексним); 2) процес удосконалення та роз...', description: 'Принципи забезпечення інформаційної безпеки: 1) підхід до забезпечення інформаційної безпеки має бути системним (комплексним); 2) процес удосконалення та розвитку інформаційної безпеки має бути безперервним і здійснюватися шляхом обґрунтування та реалізації раціональних засобів, методів, заходів із застосуванням найкращого міжнародного досвіду; 3)заходи захисту від реальних та потенційних загроз інформаційній безпеці банку мають бути своєчасні й адекватні; 4)забезпечення належного рівня інформаційної безпеки банку неможливе без підтримки та контролю з боку керівників банку; 5) сталий розвиток систем інформаційної безпеки можливий лише в разі забезпечення достатності ресурсів, у тому числі фінансових.', category: 'I. General Provisions', source: 'NBU Resolution №95 п. 6' },
  { controlCode: 'NBU95-7', title: 'Принципи криптографічного захисту інформаційних систем Національного банку: 1) криптографічний захист інформації в інформаційних системах Національного банку...', description: 'Принципи криптографічного захисту інформаційних систем Національного банку: 1) криптографічний захист інформації в інформаційних системах Національного банку на ділянці зв’язку між учасником інформаційних систем Національного банку та Національним банком забезпечується застосуванням багаторівневого (ешелонованого) підходу, за яким окремо за допомогою незалежних систем криптографічного захисту інформації захищається сеансовий рівень базової еталонної моделі взаємодії відкритих систем (Open systems interconnection basic reference model, OSI/ISO) та прикладний рівень моделі взаємодії відкритих систем інформаційних систем Національного банку; 2) для захисту сеансового рівня моделі взаємодії відкритих систем інформаційних систем Національного банку використовується криптографічний протокол захисту на транспортному рівні (Transport layer security, TLS), забезпечуються контроль цілісності та конфіденційність інформації. Для прикладного рівня моделі взаємодії відкритих систем інформаційних систем Національного банку використовуються такі механізми захисту: ідентифікація/автентифікація підписувача, контроль цілісності та конфіденційність на всіх етапах оброблення інформації; 3)залежно від категорії інформації щодо критерію конфіденційності, для забезпечення ідентифікації та автентифікації, використовується односпрямований (криптографічний ключ лише на стороні сервера, сувора криптографічна автентифікація сервера) або двоспрямований достовірний канал захисту на транспортному рівні (криптографічний ключ на стороні клієнта і на стороні сервера, сувора криптографічна автентифікація обох сторін з’єднання); 4) інформаційні системи Національного банку підтримують роботу криптографічного протоколу захисту на транспортному рівні останньої версії, але не нижче версії 1.2; 5) інформаційні системи Національного банку використовують криптографічні набори захисту на транспортному рівні лише з шифруванням та застосовують симетричні криптографічні алгоритми з довжиною ключа не менше ніж 128 біт; 6) Департамент безпеки Національного банку надає криптобібліотеки для криптографічних засобів захисту інформації, рекомендації щодо їх використання та програмне забезпечення генерації ключів.', category: 'I. General Provisions', source: 'NBU Resolution №95 п. 7' },
  { controlCode: 'NBU95-8', title: 'Банк зобов’язаний упровадити систему управління інформаційною безпекою (далі – СУІБ) згідно з ДСТУ ISO/IEC 27001:2015 для визначеної сфери застосування з ура...', description: 'Банк зобов’язаний упровадити систему управління інформаційною безпекою (далі – СУІБ) згідно з ДСТУ ISO/IEC 27001:2015 для визначеної сфери застосування з урахуванням обов’язкових вимог щодо впровадження СУІБ, викладених у розділі ІІ цього Положення.', category: 'ISMS Prerequisites', source: 'NBU Resolution №95 п. 8' },
  { controlCode: 'NBU95-9', title: 'Передумовами впровадження СУІБ у банку є: 1) упровадження процесного підходу до діяльності банку; 2) упровадження ризик-орієнтованого підходу до забезпечення...', description: 'Передумовами впровадження СУІБ у банку є: 1) упровадження процесного підходу до діяльності банку; 2) упровадження ризик-орієнтованого підходу до забезпечення інформаційної безпеки банку.', category: 'ISMS Prerequisites', source: 'NBU Resolution №95 п. 9' },
  { controlCode: 'NBU95-10', title: 'Банк зобов’язаний запровадити процес управління ризиками інформаційної безпеки в рамках системи управління ризиками банку. Банк має право самостійно визначат...', description: 'Банк зобов’язаний запровадити процес управління ризиками інформаційної безпеки в рамках системи управління ризиками банку. Банк має право самостійно визначати підходи (методики) оцінювання та оброблення ризиків інформаційної безпеки.', category: 'ISMS Prerequisites', source: 'NBU Resolution №95 п. 10' },
  { controlCode: 'NBU95-11', title: 'Банк зобов’язаний запровадити, використовуючи ризик-орієнтований підхід, заходи безпеки, визначені додатком А до ДСТУ ISO/IEC 27001:2015, згідно з ДСТУ ISO/I...', description: 'Банк зобов’язаний запровадити, використовуючи ризик-орієнтований підхід, заходи безпеки, визначені додатком А до ДСТУ ISO/IEC 27001:2015, згідно з ДСТУ ISO/IEC 27002:2015 та з урахуванням обов’язкових вимог щодо організації заходів безпеки інформації, викладених у розділах IV і V цього Положення.', category: 'ISMS Prerequisites', source: 'NBU Resolution №95 п. 11' },
  { controlCode: 'NBU95-12', title: 'Банк зобов’язаний визначити мінімальною сферою застосування СУІБ усі критичні бізнес-процеси банку. Банк має право розширити сферу застосування СУІБ банку ві...', description: 'Банк зобов’язаний визначити мінімальною сферою застосування СУІБ усі критичні бізнес-процеси банку. Банк має право розширити сферу застосування СУІБ банку відповідно до особливостей його діяльності, характеру та обсягу банківських, фінансових послуг та інших видів діяльності.', category: 'ISMS Prerequisites', source: 'NBU Resolution №95 п. 12' },
  { controlCode: 'NBU95-13', title: 'Національний банк має право здійснювати перевірку стану впровадження СУІБ банку та повноту виконання заходів безпеки інформації, що встановлені цим Положення...', description: 'Національний банк має право здійснювати перевірку стану впровадження СУІБ банку та повноту виконання заходів безпеки інформації, що встановлені цим Положенням. II. Вимоги щодо впровадження СУІБ', category: 'ISMS Prerequisites', source: 'NBU Resolution №95 п. 13' },
  { controlCode: 'NBU95-14', title: 'Банк зобов’язаний сформувати колективний керівний орган з питань впровадження та функціонування СУІБ (далі – керівний орган СУІБ) або наділити цими повноваже...', description: 'Банк зобов’язаний сформувати колективний керівний орган з питань впровадження та функціонування СУІБ (далі – керівний орган СУІБ) або наділити цими повноваженнями існуючий колективний керівний орган банку та розробити положення про керівний орган СУІБ банку з чітким визначенням його завдань, функцій та відповідальності.', category: 'II. ISMS Implementation', source: 'NBU Resolution №95 п. 14' },
  { controlCode: 'NBU95-15', title: '4. Це Положення не встановлює вимог щодо: 1) фізичної безпеки приміщень банків, технічного захисту інформації для приміщень банків, використання криптографіч...', description: '4. Це Положення не встановлює вимог щодо: 1) фізичної безпеки приміщень банків, технічного захисту інформації для приміщень банків, використання криптографічних засобів захисту інформації Національного банку в інформаційних системах Національного банку, вимоги до яких визначені відповідними нормативно-правовими актами Національного банку; 2) використання хмарних технологій/сервісів (Сloud technologies) у сфері автоматизації, технічної й технологічної підтримки діяльності банків, вимоги до яких визначаються окремим документом. 5. Вимоги цього Положення поширюються на банки. Вимоги розділу ІІІ цього Положення також поширюються на небанківські установи – учасників інформаційних систем Національного банку. 6. Принципи забезпечення інформаційної безпеки: 1) підхід до забезпечення інформаційної безпеки має бути системним (комплексним); 2) процес удосконалення та розвитку інформаційної безпеки має бути безперервним і здійснюватися шляхом обґрунтування та реалізації раціональних засобів, методів, заходів із застосуванням найкращого міжнародного досвіду; 3)заходи захисту від реальних та потенційних загроз інформаційній безпеці банку мають бути своєчасні й адекватні; 4)забезпечення належного рівня інформаційної безпеки банку неможливе без підтримки та контролю з боку керівників банку; 5) сталий розвиток систем інформаційної безпеки можливий лише в разі забезпечення достатності ресурсів, у тому числі фінансових. 7. Принципи криптографічного захисту інформаційних систем Національного банку: 1) криптографічний захист інформації в інформаційних системах Національного банку на ділянці зв’язку між учасником інформаційних систем Національного банку та Національним банком забезпечується застосуванням багаторівневого (ешелонованого) підходу, за яким окремо за допомогою незалежних систем криптографічного захисту інформації захищається сеансовий рівень базової еталонної моделі взаємодії відкритих систем (Open systems interconnection basic reference model, OSI/ISO) та прикладний рівень моделі взаємодії відкритих систем інформаційних систем Національного банку; 2) для захисту сеансового рівня моделі взаємодії відкритих систем інформаційних систем Національного банку використовується криптографічний протокол захисту на транспортному рівні (Transport layer security, TLS), забезпечуються контроль цілісності та конфіденційність інформації. Для прикладного рівня моделі взаємодії відкритих систем інформаційних систем Національного банку використовуються такі механізми захисту: ідентифікація/автентифікація підписувача, контроль цілісності та конфіденційність на всіх етапах оброблення інформації; 3)залежно від категорії інформації щодо критерію конфіденційності, для забезпечення ідентифікації та автентифікації, використовується односпрямований (криптографічний ключ лише на стороні сервера, сувора криптографічна автентифікація сервера) або двоспрямований достовірний канал захисту на транспортному рівні (криптографічний ключ на стороні клієнта і на стороні сервера, сувора криптографічна автентифікація обох сторін з’єднання); 4) інформаційні системи Національного банку підтримують роботу криптографічного протоколу захисту на транспортному рівні останньої версії, але не нижче версії 1.2; 5) інформаційні системи Національного банку використовують криптографічні набори захисту на транспортному рівні лише з шифруванням та застосовують симетричні криптографічні алгоритми з довжиною ключа не менше ніж 128 біт; 6) Департамент безпеки Національного банку надає криптобібліотеки для криптографічних засобів захисту інформації, рекомендації щодо їх використання та програмне забезпечення генерації ключів. 8. Банк зобов’язаний упровадити систему управління інформаційною безпекою (далі – СУІБ) згідно з ДСТУ ISO/IEC 27001:2015 для визначеної сфери застосування з урахуванням обов’язкових вимог щодо впровадження СУІБ, викладених у розділі ІІ цього Положення. 9. Передумовами впровадження СУІБ у банку є: 1) упровадження процесного підходу до діяльності банку; 2) упровадження ризик-орієнтованого підходу до забезпечення інформаційної безпеки банку. 10. Банк зобов’язаний запровадити процес управління ризиками інформаційної безпеки в рамках системи управління ризиками банку. Банк має право самостійно визначати підходи (методики) оцінювання та оброблення ризиків інформаційної безпеки. 11. Банк зобов’язаний запровадити, використовуючи ризик-орієнтований підхід, заходи безпеки, визначені додатком А до ДСТУ ISO/IEC 27001:2015, згідно з ДСТУ ISO/IEC 27002:2015 та з урахуванням обов’язкових вимог щодо організації заходів безпеки інформації, викладених у розділах IV і V цього Положення. 12. Банк зобов’язаний визначити мінімальною сферою застосування СУІБ усі критичні бізнес-процеси банку. Банк має право розширити сферу застосування СУІБ банку відповідно до особливостей його діяльності, характеру та обсягу банківських, фінансових послуг та інших видів діяльності. 13. Національний банк має право здійснювати перевірку стану впровадження СУІБ банку та повноту виконання заходів безпеки інформації, що встановлені цим Положенням. II. Вимоги щодо впровадження СУІБ 14. Банк зобов’язаний сформувати колективний керівний орган з питань впровадження та функціонування СУІБ (далі – керівний орган СУІБ) або наділити цими повноваженнями існуючий колективний керівний орган банку та розробити положення про керівний орган СУІБ банку з чітким визначенням його завдань, функцій та відповідальності. 15. Банк зобов’язаний включити до складу керівного органу СУІБ голову правління банку та/або його заступника, що відповідає за інформаційну безпеку банку, керівників підрозділів банку – власників критичних бізнес-процесів банку та керівника підрозділу банку з управління ризиками. Банк має право ввести до складу керівного органу СУІБ інших працівників банку відповідно до потреб, що обумовлені особливостями діяльності банку.', category: 'II. ISMS Implementation', source: 'NBU Resolution №95 п. 15' },
  { controlCode: 'NBU95-16', title: 'Банк зобов’язаний покласти на керівний орган СУІБ обов’язок виконання таких завдань: 1) погодження та перегляд політики інформаційної безпеки, положення щодо...', description: 'Банк зобов’язаний покласти на керівний орган СУІБ обов’язок виконання таких завдань: 1) погодження та перегляд політики інформаційної безпеки, положення щодо застосовності та стратегії розвитку інформаційної безпеки банку; 2) узгодження впровадження нових проектів, напрямів, стратегічних завдань з питань інформаційної безпеки банку та заходів інформаційної безпеки; 3) розгляд, затвердження та контроль за виконанням проектів щодо розроблення, упровадження, функціонування, моніторингу, перегляду, підтримання та вдосконалення СУІБ банку; 4) визначення необхідних оптимальних ресурсів для впровадження заходів інформаційної безпеки; 5) організація практичних заходів щодо підвищення обізнаності/ навчання персоналу банку з питань інформаційної безпеки; 6) забезпечення своєчасного моніторингу стану впровадження та ефективності функціонування СУІБ банку з подальшою оцінкою можливостей вдосконалення та потреби проведення коригувальних дій.', category: 'II. ISMS Implementation', source: 'NBU Resolution №95 п. 16' },
  { controlCode: 'NBU95-17', title: 'Банк зобов’язаний розробити та впровадити політику інформаційної безпеки, яка має містити: 1) цілі інформаційної безпеки; 2) сферу застосування політики інфо...', description: 'Банк зобов’язаний розробити та впровадити політику інформаційної безпеки, яка має містити: 1) цілі інформаційної безпеки; 2) сферу застосування політики інформаційної безпеки; 3) принципи, правила та вимоги інформаційної безпеки в банку; 4) визначення функцій (ролей) і відповідальності за забезпечення інформаційної безпеки.', category: 'II. ISMS Implementation', source: 'NBU Resolution №95 п. 17' },
  { controlCode: 'NBU95-18', title: 'Банк зобов’язаний забезпечити підтримку політики інформаційної безпеки в актуальному стані та її перегляд не рідше ніж один раз на рік. Якщо за результатами ...', description: 'Банк зобов’язаний забезпечити підтримку політики інформаційної безпеки в актуальному стані та її перегляд не рідше ніж один раз на рік. Якщо за результатами перегляду зміни до політики інформаційної безпеки не вносяться, то повторне її затвердження не потрібно.', category: 'II. ISMS Implementation', source: 'NBU Resolution №95 п. 18' },
  { controlCode: 'NBU95-19', title: 'Банк зобов’язаний затвердити політику інформаційної безпеки і довести її зміст до відома всього персоналу банку та, за необхідності, представникам третіх сто...', description: 'Банк зобов’язаний затвердити політику інформаційної безпеки і довести її зміст до відома всього персоналу банку та, за необхідності, представникам третіх сторін.', category: 'II. ISMS Implementation', source: 'NBU Resolution №95 п. 19' },
  { controlCode: 'NBU95-20', title: 'Банк зобов’язаний розробити та затвердити стратегію розвитку інформаційної безпеки. Банк має право затвердити стратегію розвитку інформаційної безпеки банку ...', description: 'Банк зобов’язаний розробити та затвердити стратегію розвитку інформаційної безпеки. Банк має право затвердити стратегію розвитку інформаційної безпеки банку в документі, яким затверджено загальну стратегію розвитку банку, у вигляді окремого розділу. Зміст стратегії має узгоджуватися з політикою інформаційної безпеки банку, основними стратегічними цілями банку, що пов’язані із впровадженням нових бізнес-процесів/банківських продуктів з використанням технологій, які потребують захисту інформації, а також враховувати планування розвитку інфраструктури банку та заходів інформаційної безпеки для мінімізації ризиків інформаційної безпеки.', category: 'II. ISMS Implementation', source: 'NBU Resolution №95 п. 20' },
  { controlCode: 'NBU95-21', title: 'Банк зобов’язаний розробити та затвердити план забезпечення безперервності діяльності банку, у якому враховано безперервність функціонування заходів інформац...', description: 'Банк зобов’язаний розробити та затвердити план забезпечення безперервності діяльності банку, у якому враховано безперервність функціонування заходів інформаційної безпеки в рамках процесу управління безперервністю діяльності банку.', category: 'II. ISMS Implementation', source: 'NBU Resolution №95 п. 21' },
  { controlCode: 'NBU95-22', title: 'Банк має право розробляти документи СУІБ у формі окремих документів або об’єднаних за типом (тематикою) в загальні документи, із зазначенням у них розділів, ...', description: 'Банк має право розробляти документи СУІБ у формі окремих документів або об’єднаних за типом (тематикою) в загальні документи, із зазначенням у них розділів, що відповідають визначеним напрямам (питанням) інформаційної безпеки. III. Криптографічний захист інформації в інформаційних системах Національного банку', category: 'II. ISMS Implementation', source: 'NBU Resolution №95 п. 22' },
  { controlCode: 'NBU95-23', title: 'Учасники інформаційних систем Національного банку зобов’язані налаштувати системи криптографічного захисту інформації в інформаційних системах Національного ...', description: 'Учасники інформаційних систем Національного банку зобов’язані налаштувати системи криптографічного захисту інформації в інформаційних системах Національного банку згідно з вимогами, які визначені у відповідній експлуатаційній документації кожної інформаційної системи Національного банку.', category: 'III. NBU IS Cryptography', source: 'NBU Resolution №95 п. 23' },
  { controlCode: 'NBU95-24', title: 'Банк зобов’язаний забезпечити захист інформаційних систем банку від несанкціонованого доступу та дій, направлених на відмову в обслуговуванні відповідно до в...', description: 'Банк зобов’язаний забезпечити захист інформаційних систем банку від несанкціонованого доступу та дій, направлених на відмову в обслуговуванні відповідно до вимог розділу IV цього Положення. IV. Заходи безпеки інформації', category: 'III. NBU IS Cryptography', source: 'NBU Resolution №95 п. 24' },
  { controlCode: 'NBU95-25', title: 'Банк зобов’язаний призначити відповідальну особу за інформаційну безпеку банку (Chief information security officer, CISO), яка має повноваження, достатні для...', description: 'Банк зобов’язаний призначити відповідальну особу за інформаційну безпеку банку (Chief information security officer, CISO), яка має повноваження, достатні для прийняття управлінських рішень (посада не нижче заступника голови правління банку), та забезпечує: 1) стратегічне керівництво з питань інформаційної безпеки банку; 2) визначення напрямів розвитку інформаційної безпеки банку, їх відповідність стратегії розвитку банку; 3) відповідність заходів безпеки інформації потребам бізнес процесів/банківських продуктів; 4) контроль за впровадженням заходів безпеки інформації в банку.', category: 'Organization & Awareness', source: 'NBU Resolution №95 п. 25' },
  { controlCode: 'NBU95-26', title: 'Банк зобов’язаний сформувати підрозділ з інформаційної безпеки не менше як із двох працівників зі складу штатних працівників банку. Підрозділ з інформаційної...', description: 'Банк зобов’язаний сформувати підрозділ з інформаційної безпеки не менше як із двох працівників зі складу штатних працівників банку. Підрозділ з інформаційної безпеки банку має безпосередньо підпорядковуватися відповідальній особі за інформаційну безпеку банку.', category: 'Organization & Awareness', source: 'NBU Resolution №95 п. 26' },
  { controlCode: 'NBU95-27', title: 'Підрозділ з інформаційної безпеки банку має здійснювати: 1) розроблення вимог щодо налаштувань безпеки інформаційних систем банку; 2) розроблення або участь ...', description: 'Підрозділ з інформаційної безпеки банку має здійснювати: 1) розроблення вимог щодо налаштувань безпеки інформаційних систем банку; 2) розроблення або участь у розробленні документів банку щодо інформаційної безпеки; 3) контроль за виконанням заходів щодо забезпечення безпеки інформації на всіх стадіях життєвого циклу інформаційних систем банку; 4) розслідування інцидентів безпеки інформації; 5) спільно з підрозділами інформаційних технологій (інформатизації, автоматизації) банку відновлення функціонування інформаційних систем банку після збоїв у роботі внаслідок інцидентів безпеки інформації.', category: 'Organization & Awareness', source: 'NBU Resolution №95 п. 27' },
  { controlCode: 'NBU95-28', title: 'Працівникам підрозділу інформаційної безпеки/відповідальній особі за інформаційну безпеку банку забороняється мати повноваження з розроблення, упровадження, ...', description: 'Працівникам підрозділу інформаційної безпеки/відповідальній особі за інформаційну безпеку банку забороняється мати повноваження з розроблення, упровадження, супроводження (адміністрування) та експлуатації інформаційних систем банку, крім тих, що використовуються для забезпечення безпеки інформації.', category: 'Organization & Awareness', source: 'NBU Resolution №95 п. 28' },
  { controlCode: 'NBU95-29', title: 'Підрозділу інформаційних технологій (інформатизації, автоматизації) банку забороняється бути власником інформаційних систем банку, які безпосередньо забезпеч...', description: 'Підрозділу інформаційних технологій (інформатизації, автоматизації) банку забороняється бути власником інформаційних систем банку, які безпосередньо забезпечують автоматизацію банківської діяльності.', category: 'Organization & Awareness', source: 'NBU Resolution №95 п. 29' },
  { controlCode: 'NBU95-30', title: 'Банк зобов’язаний ознайомити працівників під час прийому на роботу з політикою інформаційної безпеки банку. Працівник банку зобов’язаний ознайомитися з політ...', description: 'Банк зобов’язаний ознайомити працівників під час прийому на роботу з політикою інформаційної безпеки банку. Працівник банку зобов’язаний ознайомитися з політикою інформаційної безпеки банку під підпис та надати зобов’язання про дотримання конфіденційності.', category: 'Organization & Awareness', source: 'NBU Resolution №95 п. 30' },
  { controlCode: 'NBU95-31', title: 'Банк зобов’язаний включити до трудового контракту/договору працівника та/або посадової інструкції працівника обов’язки працівника банку щодо виконання вимог ...', description: 'Банк зобов’язаний включити до трудового контракту/договору працівника та/або посадової інструкції працівника обов’язки працівника банку щодо виконання вимог із забезпечення безпеки інформації.', category: 'Organization & Awareness', source: 'NBU Resolution №95 п. 31' },
  { controlCode: 'NBU95-32', title: 'Банк зобов’язаний ознайомити працівників банку з внутрішніми документами банку, які встановлюють вимоги щодо безпеки інформації. Документи розробляються банк...', description: 'Банк зобов’язаний ознайомити працівників банку з внутрішніми документами банку, які встановлюють вимоги щодо безпеки інформації. Документи розробляються банком з урахуванням вимог цього Положення. Перелік документів для ознайомлення визначається банком самостійно, з урахуванням принципу мінімального рівня повноважень. Працівник банку зобов’язаний ознайомитися з такими документами під підпис. навчання працівників отриманого за результатами вирішення інцидентів безпеки інформації.', category: 'Organization & Awareness', source: 'NBU Resolution №95 п. 32' },
  { controlCode: 'NBU95-33', title: 'Банк зобов’язаний упровадити програму підвищення обізнаності/ банку з питань безпеки інформації з урахуванням досвіду, встановлюють вимоги щодо безпеки інфор...', description: 'Банк зобов’язаний упровадити програму підвищення обізнаності/ банку з питань безпеки інформації з урахуванням досвіду, встановлюють вимоги щодо безпеки інформації під час використання носіїв інформації і мають', category: 'Organization & Awareness', source: 'NBU Resolution №95 п. 33' },
  { controlCode: 'NBU95-34', title: 'Банк зобов’язаний розробити та затвердити внутрішні документи, які змінних містити положення щодо: процедури їх обліку та виведення з експлуатації; 1) контро...', description: 'Банк зобов’язаний розробити та затвердити внутрішні документи, які змінних містити положення щодо: процедури їх обліку та виведення з експлуатації; 1) контролю за використанням змінних носіїв інформації, уключаючи інформації; 2) категорії інформації, яка може оброблятися на змінних носіях 3) ідентифікації змінних носіїв інформації, які використовуються в банку; межами банку); 4) обмежень використання змінних носіїв інформації (у тому числі поза передаванням виведенням з експлуатації; 5) знищення інформації на змінних носіях інформації перед їх у користування іншому працівникові банку, третім сторонам або зловмисного коду перед використанням у 6) обов’язковості перевірки змінних носіїв інформації на наявність банку. за допомогою унікального ідентифікатора, який дозволить визначити тип носія та користувача змінного носія.', category: 'Removable Media', source: 'NBU Resolution №95 п. 34' },
  { controlCode: 'NBU95-35', title: 'Банк зобов’язаний здійснити ідентифікацію змінних носіїв інформації встановлюють вимоги щодо використання, надання, скасування та контролю доступу до інформа...', description: 'Банк зобов’язаний здійснити ідентифікацію змінних носіїв інформації встановлюють вимоги щодо використання, надання, скасування та контролю доступу до інформаційних систем банку і мають містити:', category: 'Removable Media', source: 'NBU Resolution №95 п. 35' },
  { controlCode: 'NBU95-36', title: 'Банк зобов’язаний розробити та затвердити внутрішні документи, які 1) вимоги до ідентифікації, автентифікації, авторизації користувачів; віддаленого доступу)...', description: 'Банк зобов’язаний розробити та затвердити внутрішні документи, які 1) вимоги до ідентифікації, автентифікації, авторизації користувачів; віддаленого доступу); 2) послідовність дій під час управління доступом, у тому числі в разі доступу (реєстрація, надання повноважень, перегляд та скасування банку; 3) перелік типових функцій та прав доступу до інформаційних систем 4) вимоги щодо здійснення заходів контролю доступу, уключаючи контроль за діями привілейованих користувачів; 5) періодичність контролю наданих прав доступу; 6) вимоги до протоколювання дій під час управління доступом.', category: 'Access Control', source: 'NBU Resolution №95 п. 36' },
  { controlCode: 'NBU95-37', title: 'Банк зобов’язаний забезпечити дотримання принципу надання мінімального рівня повноважень під час надання доступу до інформаційних систем банку (уключаючи дос...', description: 'Банк зобов’язаний забезпечити дотримання принципу надання мінімального рівня повноважень під час надання доступу до інформаційних систем банку (уключаючи доступ привілейованих користувачів).', category: 'Access Control', source: 'NBU Resolution №95 п. 37' },
  { controlCode: 'NBU95-38', title: 'В інформаційних системах банку, які безпосередньо забезпечують автоматизацію банківської діяльності, забороняється суміщення в межах однієї функції (ролі) та...', description: 'В інформаційних системах банку, які безпосередньо забезпечують автоматизацію банківської діяльності, забороняється суміщення в межах однієї функції (ролі) таких повноважень: розроблення та супроводження (адміністрування), розроблення та експлуатація, супроводження (адміністрування) та експлуатація, виконання операцій в таких системах та подальшого контролю за їх виконанням.', category: 'Access Control', source: 'NBU Resolution №95 п. 38' },
  { controlCode: 'NBU95-39', title: 'Банк зобов’язаний запровадити такі заходи контролю доступу до інформаційних систем банку: 1) перевірку наявності у користувача дозволу керівництва та власник...', description: 'Банк зобов’язаний запровадити такі заходи контролю доступу до інформаційних систем банку: 1) перевірку наявності у користувача дозволу керівництва та власника інформаційної системи на такий доступ; 2) заборону одноосібного ініціювання заявки, підтвердження та надання доступу; 3) перевірку відповідності рівня наданого доступу принципу мінімально необхідного рівня повноважень; 4) періодичну перевірку відповідності наданих прав доступу користувачеві тим, що діють на момент перевірки.', category: 'Access Control', source: 'NBU Resolution №95 п. 39' },
  { controlCode: 'NBU95-40', title: 'Банк зобов’язаний використовувати механізми багатофакторної автентифікації під час надання доступу для виконання функцій адміністрування або супроводження САБ.', description: 'Банк зобов’язаний використовувати механізми багатофакторної автентифікації під час надання доступу для виконання функцій адміністрування або супроводження САБ.', category: 'Access Control', source: 'NBU Resolution №95 п. 40' },
  { controlCode: 'NBU95-41', title: 'Банк зобов’язаний забезпечити блокування облікових записів користувачів в інформаційних системах банку в таких випадках: 1) п’яти невдалих спроб автентифікац...', description: 'Банк зобов’язаний забезпечити блокування облікових записів користувачів в інформаційних системах банку в таких випадках: 1) п’яти невдалих спроб автентифікації поспіль (автоматичне блокування); 2) відсутності реєстрації користувача в інформаційних системах банку протягом 90 календарних днів; 3) звільнення користувача.', category: 'Access Control', source: 'NBU Resolution №95 п. 41' },
  { controlCode: 'NBU95-42', title: 'Банк зобов’язаний здійснювати протоколювання всіх дій щодо надання, скасування чи зміни доступу до інформаційних систем банку, які безпосередньо забезпечують...', description: 'Банк зобов’язаний здійснювати протоколювання всіх дій щодо надання, скасування чи зміни доступу до інформаційних систем банку, які безпосередньо забезпечують автоматизацію банківської діяльності, у захищених від несанкціонованої модифікації електронних журналах із забезпеченням їх збереження не менше ніж протягом трьох років.', category: 'Access Control', source: 'NBU Resolution №95 п. 42' },
  { controlCode: 'NBU95-43', title: 'Банк зобов’язаний забезпечити протоколювання, збереження та захист від модифікації інформації про події доступу до інформаційних систем банку, які безпосеред...', description: 'Банк зобов’язаний забезпечити протоколювання, збереження та захист від модифікації інформації про події доступу до інформаційних систем банку, які безпосередньо забезпечують автоматизацію банківської діяльності, та зберігання її не менше ніж протягом одного року. криптографічних засобів для захисту інформації, яка має містити:', category: 'Access Control', source: 'NBU Resolution №95 п. 43' },
  { controlCode: 'NBU95-44', title: 'Банк зобов’язаний розробити та впровадити політику використання безпеки (конфіденційність, цілісність, доступність); 1) цілі безпеки, для яких використовують...', description: 'Банк зобов’язаний розробити та впровадити політику використання безпеки (конфіденційність, цілісність, доступність); 1) цілі безпеки, для яких використовуються криптографічні заходи захисту класифікації за критерієм конфіденційності. 2) положення щодо необхідності та застосування необхідного рівня інформації за допомогою криптографічних засобів залежно від її процес управління ключами, які мають містити положення щодо:', category: 'Cryptography', source: 'NBU Resolution №95 п. 44' },
  { controlCode: 'NBU95-45', title: 'Банк зобов’язаний розробити та затвердити документи, що описують 1) процедури генерації ключів для різних криптографічних систем; 2) розподілу ключів серед в...', description: 'Банк зобов’язаний розробити та затвердити документи, що описують 1) процедури генерації ключів для різних криптографічних систем; 2) розподілу ключів серед відповідальних осіб; 3) зберігання ключів; 4) заміни або оновлення ключів; 5) поводження із скомпрометованими ключами; 6) відкликання ключів; 7) відновлення ключів, які зруйновано; 8) процедури резервного копіювання або архівування ключів; 9) знищення ключів; 10) реєстрації та аудиту діяльності, пов’язаної з управлінням ключами. використовувати криптографічні алгоритми з такого переліку:', category: 'Cryptography', source: 'NBU Resolution №95 п. 45' },
  { controlCode: 'NBU95-46', title: 'Банк у разі застосування криптографічного захисту зобов’язаний 1) асиметричні алгоритми: сеансових ключів шифрування; підписів; для узгодження сеансових ключ...', description: 'Банк у разі застосування криптографічного захисту зобов’язаний 1) асиметричні алгоритми: сеансових ключів шифрування; підписів; для узгодження сеансових ключів шифрування; ECDSA) для цифрових підписів; цифрових підписів і узгодження сеансових ключів шифрування ключів; Криптографічний еліптичних Державного комітету України з питань технічного регулювання та споживчої політики від 28 грудня 2002 року № 31 (далі – підписів; алгоритм Діффі – Геллмана (далі – алгоритм DH) для узгодження алгоритм цифрового підпису (далі – алгоритм DSA) для цифрових алгоритм Діффі – Геллмана на еліптичних кривих (далі – алгоритм ECDH) алгоритм цифрового підпису на еліптичних кривих (далі – алгоритм алгоритм Ривест – Шаміра – Адлемана (далі – алгоритм RSA) для або аналогічних алгоритм цифрового підпису [ДСТУ 4145-2002 “Інформаційні технології. захист інформації. Цифровий підпис, що ґрунтується на кривих. Формування та перевіряння”, затверджений наказом ДСТУ 4145-2002)] для цифрових “Купина” (ДСТУ 7564:2014 “Інформаційні технології. Криптографічний захист інформації. Функція гешування”, прийнятий наказом Міністерства економічного розвитку криптостійкі; 2) алгоритми безпеки гешування SHA-224, SHA-256, SHA-384, SHA-512, і торгівлі України від 02 грудня 2014 року № 1431) або більш 3) алгоритми симетричного шифрування: ключа 128, 192 і 256 біт або більше; алгоритм “Advanced encryption standard” (AES) із використанням довжини 3) алгоритми симетричного шифрування: алгоритм “Advanced encryption standard” (AES) із використанням довжини ключа 128, 192 і 256 біт або більше; алгоритм криптографічного перетворення (ДСТУ ГОСТ 28147:2009 “Система оброблення інформації. Захист криптографічний. Алгоритм криптографічного перетворення”, прийнятий наказом Державного комітету України з питань технічного регулювання та споживчої політики від 22 грудня 2008 року № 495); алгоритм “Калина” (ДСТУ 7624:2014 “Інформаційні технології. Криптографічний захист інформації. Алгоритм симетричного блокового перетворення”, прийнятий наказом Міністерства економічного розвитку і торгівлі України від 29 грудня 2014 року № 1484). шифрування, зобов’язаний біт.', category: 'Cryptography', source: 'NBU Resolution №95 п. 46' },
  { controlCode: 'NBU95-47', title: 'Банк, який застосовує алгоритм DH для узгодження сеансових ключів використовувати розмір модуля не менше ніж 2048 зобов’язаний використовувати розмір модуля ...', description: 'Банк, який застосовує алгоритм DH для узгодження сеансових ключів використовувати розмір модуля не менше ніж 2048 зобов’язаний використовувати розмір модуля не менше ніж 2048 біт.', category: 'Cryptography', source: 'NBU Resolution №95 п. 47' },
  { controlCode: 'NBU95-48', title: 'Банк, який застосовує алгоритм DSA для цифрових підписів, використовувати стандарту standards,', description: 'Банк, який застосовує алгоритм DSA для цифрових підписів, використовувати стандарту standards,', category: 'Cryptography', source: 'NBU Resolution №95 п. 48' },
  { controlCode: 'NBU95-49', title: 'Банк, який застосовує алгоритм на еліптичних кривих, зобов’язаний еліптичні криві з ДСТУ 4145-2002 або з Федерального оброблення інформації (США) (Federal in...', description: 'Банк, який застосовує алгоритм на еліптичних кривих, зобов’язаний еліптичні криві з ДСТУ 4145-2002 або з Федерального оброблення інформації (США) (Federal information processing FIPS186-4). ключів менший,', category: 'Cryptography', source: 'NBU Resolution №95 п. 49' },
  { controlCode: 'NBU95-50', title: 'Банк, який застосовує алгоритм ECDH для узгодження сеансових шифрування, зобов’язаний використовувати розмір поля/ключа не ніж 160 біт. цифрових менший,', description: 'Банк, який застосовує алгоритм ECDH для узгодження сеансових шифрування, зобов’язаний використовувати розмір поля/ключа не ніж 160 біт. цифрових менший,', category: 'Cryptography', source: 'NBU Resolution №95 п. 50' },
  { controlCode: 'NBU95-51', title: 'Банк, який застосовує алгоритми ECDSA, ДСТУ 4145-2002 для підписів, зобов’язаний використовувати розмір поля/ключа не ніж 160 біт. шифрування розмір модуля н...', description: 'Банк, який застосовує алгоритми ECDSA, ДСТУ 4145-2002 для підписів, зобов’язаний використовувати розмір поля/ключа не ніж 160 біт. шифрування розмір модуля не менше ніж 2048 біт.', category: 'Cryptography', source: 'NBU Resolution №95 п. 51' },
  { controlCode: 'NBU95-52', title: 'Банк, який застосовує алгоритм RSA для цифрових підписів і ключів сеансу або аналогічних ключів, зобов’язаний використовувати шифрування сеансу або аналогічн...', description: 'Банк, який застосовує алгоритм RSA для цифрових підписів і ключів сеансу або аналогічних ключів, зобов’язаний використовувати шифрування сеансу або аналогічних ключів, зобов’язаний використовувати різні ключові ключів)', category: 'Cryptography', source: 'NBU Resolution №95 п. 52' },
  { controlCode: 'NBU95-53', title: 'Банк, який застосовує алгоритм RSA для цифрових підписів і ключів пари для передавання ключів шифрування сеансу (або аналогічних та для цифрових підписів. на...', description: 'Банк, який застосовує алгоритм RSA для цифрових підписів і ключів пари для передавання ключів шифрування сеансу (або аналогічних та для цифрових підписів. на транспортному рівні повторне протоколом погодження', category: 'Cryptography', source: 'NBU Resolution №95 п. 53' },
  { controlCode: 'NBU95-54', title: 'Банк зобов’язаний використовувати останню версію протоколу захисту та реалізацію цього протоколу, що підтримує безпечне погодження з’єднання для захисту з’єд...', description: 'Банк зобов’язаний використовувати останню версію протоколу захисту та реалізацію цього протоколу, що підтримує безпечне погодження з’єднання для захисту з’єднань, які управляються Transmission control protocol (TCP). Якщо безпечне повторне з’єднання не підтримується, то ця процедура має бути відключена. алгоритму DH.', category: 'Cryptography', source: 'NBU Resolution №95 п. 54' },
  { controlCode: 'NBU95-55', title: 'Банку забороняється використання анонімного (без автентифікації) internet стандарт не нижче версії 3.0.', description: 'Банку забороняється використання анонімного (без автентифікації) internet стандарт не нижче версії 3.0.', category: 'Cryptography', source: 'NBU Resolution №95 п. 55' },
  { controlCode: 'NBU95-56', title: 'Банк, який застосовує стандарти для шифрування “Secure multipurpose mail extension” (далі – S/MIME), зобов’язаний використовувати цей захисту протоколів Inte...', description: 'Банк, який застосовує стандарти для шифрування “Secure multipurpose mail extension” (далі – S/MIME), зобов’язаний використовувати цей захисту протоколів Internet protocol security, IPsec) у режимі ESP (Encapsulating security', category: 'Cryptography', source: 'NBU Resolution №95 п. 56' },
  { controlCode: 'NBU95-57', title: 'Банк зобов’язаний використовувати набір протоколів для забезпечення даних, що передаються за допомогою протоколу Інтернету (набір payload) (якщо банк не вико...', description: 'Банк зобов’язаний використовувати набір протоколів для забезпечення даних, що передаються за допомогою протоколу Інтернету (набір payload) (якщо банк не використовує криптографічний протокол захисту на транспортному рівні).', category: 'Cryptography', source: 'NBU Resolution №95 п. 57' },
  { controlCode: 'NBU95-58', title: 'Банк зобов’язаний використовувати кабелі типу “вита пара” не нижче категорії 5E та/або оптично-волоконні кабелі для організації структурованої кабельної сист...', description: 'Банк зобов’язаний використовувати кабелі типу “вита пара” не нижче категорії 5E та/або оптично-волоконні кабелі для організації структурованої кабельної системи (далі – СКС).', category: 'Structured Cabling', source: 'NBU Resolution №95 п. 58' },
  { controlCode: 'NBU95-59', title: 'Банк зобов’язаний забезпечити наявність та актуальність такої документації до СКС: 1) схеми (креслення) розміщення обладнання СКС та кабельних каналів; 2) сх...', description: 'Банк зобов’язаний забезпечити наявність та актуальність такої документації до СКС: 1) схеми (креслення) розміщення обладнання СКС та кабельних каналів; 2) схеми підключення обладнання СКС; 3) таблиці маркування кабелів СКС та кабельних з’єднань (кабельний журнал).', category: 'Structured Cabling', source: 'NBU Resolution №95 п. 59' },
  { controlCode: 'NBU95-60', title: 'Банк зобов’язаний забезпечити персоналізований та контрольований доступ до комутаційних вузлів СКС.', description: 'Банк зобов’язаний забезпечити персоналізований та контрольований доступ до комутаційних вузлів СКС.', category: 'Structured Cabling', source: 'NBU Resolution №95 п. 60' },
  { controlCode: 'NBU95-61', title: 'Банк зобов’язаний розробити та затвердити внутрішній документ, який установлює вимоги до забезпечення захисту від зловмисного коду та описує організацію захи...', description: 'Банк зобов’язаний розробити та затвердити внутрішній документ, який установлює вимоги до забезпечення захисту від зловмисного коду та описує організацію захисту від зловмисного коду в банку, який має містити положення щодо: 1) вимог до безперервного забезпечення захисту від зловмисного коду; 2) вимог до застосування засобів захисту від зловмисного коду, контролю за їх належним функціонуванням та періодичністю оновлення, з обов’язковим визначенням відповідальних осіб; 3) застосування оновлень для засобів захисту від зловмисного коду та баз даних засобів захисту від зловмисного коду на робочих станціях та серверах, що не підключені до мережі банку; 4) опису процедури централізованого розгортання та управління засобами захисту від зловмисного коду; 5) вимог до проведення профілактичних заходів з виявлення зловмисного коду в інформаційних системах банку та їх періодичності.', category: 'Malware Protection', source: 'NBU Resolution №95 п. 61' },
  { controlCode: 'NBU95-62', title: 'Банк зобов’язаний використовувати виключно актуальні версії ліцензійних засобів захисту від зловмисного коду, для яких не припинено підтримку виробника.', description: 'Банк зобов’язаний використовувати виключно актуальні версії ліцензійних засобів захисту від зловмисного коду, для яких не припинено підтримку виробника.', category: 'Malware Protection', source: 'NBU Resolution №95 п. 62' },
  { controlCode: 'NBU95-63', title: 'Банк зобов’язаний здійснювати централізоване управління захистом від зловмисного коду та забезпечувати можливість: 1) віддаленого встановлення, видалення, он...', description: 'Банк зобов’язаний здійснювати централізоване управління захистом від зловмисного коду та забезпечувати можливість: 1) віддаленого встановлення, видалення, оновлення та конфігурації засобів захисту від зловмисного коду; 2) реєстрації всіх подій засобів захисту від зловмисного коду та централізованого зберігання такої інформації (електронних журналів); 3) контролю за наявністю та коректністю роботи агентів засобів захисту від зловмисного коду на робочих станціях та серверах банку.', category: 'Malware Protection', source: 'NBU Resolution №95 п. 63' },
  { controlCode: 'NBU95-64', title: 'Банк зобов’язаний забезпечити перевірку програмними та/або програмно-апаратними засобами захисту від зловмисного коду: 1) усіх вхідних та вихідних повідомлен...', description: 'Банк зобов’язаний забезпечити перевірку програмними та/або програмно-апаратними засобами захисту від зловмисного коду: 1) усіх вхідних та вихідних повідомлень корпоративної електронної пошти, уключаючи вкладення до них; 2) усього вхідного Інтернет-трафіку; 3) усіх змінних носіїв інформації, що підключаються до робочих станцій або іншого обладнання інформаційних систем банку.', category: 'Malware Protection', source: 'NBU Resolution №95 п. 64' },
  { controlCode: 'NBU95-65', title: 'Банк зобов’язаний запровадити заходи, що забезпечують захист від несанкціонованого видалення, відключення та скасування оновлень засобів захисту від зловмисн...', description: 'Банк зобов’язаний запровадити заходи, що забезпечують захист від несанкціонованого видалення, відключення та скасування оновлень засобів захисту від зловмисного коду, а також від зміни їх налаштувань та конфігурації.', category: 'Malware Protection', source: 'NBU Resolution №95 п. 65' },
  { controlCode: 'NBU95-66', title: 'Банк зобов’язаний обробляти факти ураження інформаційних систем банку зловмисним кодом в рамках процесу управління інцидентами безпеки інформації. Банк самос...', description: 'Банк зобов’язаний обробляти факти ураження інформаційних систем банку зловмисним кодом в рамках процесу управління інцидентами безпеки інформації. Банк самостійно визначає критерії віднесення фактів вірусного ураження до інцидентів безпеки інформації.', category: 'Malware Protection', source: 'NBU Resolution №95 п. 66' },
  { controlCode: 'NBU95-67', title: 'Банк зобов’язаний здійснювати перевірку всіх переносних та/або стаціонарних носіїв інформації засобами захисту від зловмисного коду, які окремо або в складі ...', description: 'Банк зобов’язаний здійснювати перевірку всіх переносних та/або стаціонарних носіїв інформації засобами захисту від зловмисного коду, які окремо або в складі пристрою були повернуті після їх використання третіми сторонами.', category: 'Malware Protection', source: 'NBU Resolution №95 п. 67' },
  { controlCode: 'NBU95-68', title: 'Банк зобов’язаний зберігати електронні журнали роботи засобів захисту від зловмисного коду не менше ніж три місяці.', description: 'Банк зобов’язаний зберігати електронні журнали роботи засобів захисту від зловмисного коду не менше ніж три місяці.', category: 'Malware Protection', source: 'NBU Resolution №95 п. 68' },
  { controlCode: 'NBU95-69', title: 'Банк зобов’язаний використовувати операційні системи, для яких не припинено підтримку виробника та які забезпечують можливість: 1) ідентифікації та автентифі...', description: 'Банк зобов’язаний використовувати операційні системи, для яких не припинено підтримку виробника та які забезпечують можливість: 1) ідентифікації та автентифікації всіх користувачів операційної системи; 2) розмежування доступу користувачів операційної системи; 3) реєстрації дій, що виконуються користувачами операційної системи та самою операційною системою.', category: 'Operating Systems & Patching', source: 'NBU Resolution №95 п. 69' },
  { controlCode: 'NBU95-70', title: 'Банк зобов’язаний використовувати офіційні стабільні версії прикладного програмного забезпечення та драйверів, для яких не припинено підтримку виробника.', description: 'Банк зобов’язаний використовувати офіційні стабільні версії прикладного програмного забезпечення та драйверів, для яких не припинено підтримку виробника.', category: 'Operating Systems & Patching', source: 'NBU Resolution №95 п. 70' },
  { controlCode: 'NBU95-71', title: 'Банк зобов’язаний визначити стандартне еталонне джерело часу та забезпечити синхронізацію з ним операційних систем.', description: 'Банк зобов’язаний визначити стандартне еталонне джерело часу та забезпечити синхронізацію з ним операційних систем.', category: 'Operating Systems & Patching', source: 'NBU Resolution №95 п. 71' },
  { controlCode: 'NBU95-72', title: 'Банк зобов’язаний забезпечити блокування або перейменування облікових записів користувачів операційних систем, що встановлюються за замовчуванням, та відключ...', description: 'Банк зобов’язаний забезпечити блокування або перейменування облікових записів користувачів операційних систем, що встановлюються за замовчуванням, та відключення гостьових облікових записів. Банк зобов’язаний заблокувати вбудовані облікові записи локального адміністратора операційних систем або (якщо немає технічної можливості на рівні фунціоналу операційної системи) перейменувати такі вбудовані облікові записи та змінювати їх пароль не рідше ніж один раз на 30 діб.', category: 'Operating Systems & Patching', source: 'NBU Resolution №95 п. 72' },
  { controlCode: 'NBU95-73', title: 'Банк зобов’язаний забезпечити автоматичне блокування робочого стола операційної системи на робочій станції або сервері, якщо немає активності користувача про...', description: 'Банк зобов’язаний забезпечити автоматичне блокування робочого стола операційної системи на робочій станції або сервері, якщо немає активності користувача протягом 15 хвилин, з наступною повторною автентифікацією користувача під час розблокування (за винятком робочих станцій або серверів, на яких блокування неможливе або потребує більшого інтервалу часу відсутності активності за технологією використання).', category: 'Operating Systems & Patching', source: 'NBU Resolution №95 п. 73' },
  { controlCode: 'NBU95-74', title: 'Банк зобов’язаний забезпечити централізоване розповсюдження налаштувань параметрів безпеки та інших параметрів конфігурації операційних систем (наприклад, за...', description: 'Банк зобов’язаний забезпечити централізоване розповсюдження налаштувань параметрів безпеки та інших параметрів конфігурації операційних систем (наприклад, за допомогою використання групових політик контролера домену “Active Directory”).', category: 'Operating Systems & Patching', source: 'NBU Resolution №95 п. 74' },
  { controlCode: 'NBU95-75', title: 'Банк зобов’язаний створити та підтримувати в актуальному стані перелік програмного забезпечення, що використовується в банку (в електронному або паперовому в...', description: 'Банк зобов’язаний створити та підтримувати в актуальному стані перелік програмного забезпечення, що використовується в банку (в електронному або паперовому вигляді).', category: 'Operating Systems & Patching', source: 'NBU Resolution №95 п. 75' },
  { controlCode: 'NBU95-76', title: 'Банк зобов’язаний забезпечити блокування можливості здійснення працівниками банку, яким не надано адміністративних прав у операційних системах, таких дій (на...', description: 'Банк зобов’язаний забезпечити блокування можливості здійснення працівниками банку, яким не надано адміністративних прав у операційних системах, таких дій (налаштувань): 1) самостійного встановлення програмного забезпечення, яке не внесено до переліку програмного забезпечення, що використовується в банку; 2) автоматичного запуску програм із зовнішніх пристроїв та носіїв інформації; 3) самостійного видалення встановленого програмного забезпечення, оновлень безпеки.', category: 'Operating Systems & Patching', source: 'NBU Resolution №95 п. 76' },
  { controlCode: 'NBU95-77', title: 'Банк зобов’язаний розробити та затвердити внутрішні документи, які містять опис процесу управління оновленнями (описи дій щодо отримання, тестування, розповс...', description: 'Банк зобов’язаний розробити та затвердити внутрішні документи, які містять опис процесу управління оновленнями (описи дій щодо отримання, тестування, розповсюдження та застосування оновлень операційних систем, прикладного програмного забезпечення та драйверів). Процес управління оновленнями має містити такі стадії: 1) підготовка тестового середовища (тестових клієнтів); 2) підготовка переліку оновлень; 3) застосування оновлень в тестовому середовищі; 4) застосування оновлень на пілотній групі користувачів; 5) застосування протестованих оновлень.', category: 'Operating Systems & Patching', source: 'NBU Resolution №95 п. 77' },
  { controlCode: 'NBU95-78', title: 'Банк зобов’язаний здійснювати налаштування програмного забезпечення систем управління базами даних (далі – СУБД) для роботи під окремим обліковим записом з д...', description: 'Банк зобов’язаний здійснювати налаштування програмного забезпечення систем управління базами даних (далі – СУБД) для роботи під окремим обліковим записом з дотриманням принципу надання мінімального рівня повноважень (необхідних для виконання функцій СУБД).', category: 'Database Security', source: 'NBU Resolution №95 п. 78' },
  { controlCode: 'NBU95-79', title: 'Банк зобов’язаний забезпечити блокування облікових записів адміністраторів СУБД, установлених за замовчуванням (або зміну їх паролів) та використання обліков...', description: 'Банк зобов’язаний забезпечити блокування облікових записів адміністраторів СУБД, установлених за замовчуванням (або зміну їх паролів) та використання облікових записів адміністраторів СУБД виключно для вирішення адміністративних завдань.', category: 'Database Security', source: 'NBU Resolution №95 п. 79' },
  { controlCode: 'NBU95-80', title: 'Банк зобов’язаний забезпечити видалення/блокування неперсоналізованих і гостьових облікових записів користувачів СУБД та персоналізацію технологічних обліков...', description: 'Банк зобов’язаний забезпечити видалення/блокування неперсоналізованих і гостьових облікових записів користувачів СУБД та персоналізацію технологічних облікових записів СУБД.', category: 'Database Security', source: 'NBU Resolution №95 п. 80' },
  { controlCode: 'NBU95-81', title: 'Банк зобов’язаний забезпечити фізичне або віртуальне функціональне розділення серверів СУБД та серверів застосувань інформаційних систем банку.', description: 'Банк зобов’язаний забезпечити фізичне або віртуальне функціональне розділення серверів СУБД та серверів застосувань інформаційних систем банку.', category: 'Database Security', source: 'NBU Resolution №95 п. 81' },
  { controlCode: 'NBU95-82', title: 'Банк зобов’язаний розміщувати сервери баз даних в окремому сегменті мережі банку, захищеному за допомогою міжмережевого екрана.', description: 'Банк зобов’язаний розміщувати сервери баз даних в окремому сегменті мережі банку, захищеному за допомогою міжмережевого екрана.', category: 'Database Security', source: 'NBU Resolution №95 п. 82' },
  { controlCode: 'NBU95-83', title: 'Банк зобов’язаний визначити привілейовані облікові записи для інформаційних систем банку, мережевого обладнання та серверів. Привілейовані облікові записи на...', description: 'Банк зобов’язаний визначити привілейовані облікові записи для інформаційних систем банку, мережевого обладнання та серверів. Привілейовані облікові записи надаються користувачам згідно з внутрішніми документами банку, що встановлюють вимоги до використання, надання, скасування та контролю доступу до інформаційних систем банку.', category: 'Privileged Access', source: 'NBU Resolution №95 п. 83' },
  { controlCode: 'NBU95-84', title: 'Банк зобов’язаний забезпечити розташування робочих станцій, з яких виконуються дії щодо адміністрування та супроводження інформаційних систем банку, мережево...', description: 'Банк зобов’язаний забезпечити розташування робочих станцій, з яких виконуються дії щодо адміністрування та супроводження інформаційних систем банку, мережевого обладнання та серверів банку, використовуючи привілейовані облікові записи, в окремому сегменті мережі банку, захищеному за допомогою міжмережевого екрана.', category: 'Privileged Access', source: 'NBU Resolution №95 п. 84' },
  { controlCode: 'NBU95-85', title: 'Банк зобов’язаний забезпечити надання доступу до портів адміністрування та супроводження інформаційних систем, мережевого обладнання та серверів банку виключ...', description: 'Банк зобов’язаний забезпечити надання доступу до портів адміністрування та супроводження інформаційних систем, мережевого обладнання та серверів банку виключно з IP-адрес (робочих станцій), які визначені банком для адміністрування та супроводження таких систем або обладнання.', category: 'Privileged Access', source: 'NBU Resolution №95 п. 85' },
  { controlCode: 'NBU95-86', title: 'Банк зобов’язаний забезпечити використання адміністраторами інформаційних систем банку, мережевого обладнання та серверів банку облікових записів без привіле...', description: 'Банк зобов’язаний забезпечити використання адміністраторами інформаційних систем банку, мережевого обладнання та серверів банку облікових записів без привілейованих повноважень для автентифікації на робочих станціях, які визначені банком для адміністрування та супроводження таких систем чи обладнання.', category: 'Privileged Access', source: 'NBU Resolution №95 п. 86' },
  { controlCode: 'NBU95-87', title: 'Банк зобов’язаний забезпечити використання виключно персоналізованих облікових записів для виконання адміністрування чи супроводження інформаційних систем ба...', description: 'Банк зобов’язаний забезпечити використання виключно персоналізованих облікових записів для виконання адміністрування чи супроводження інформаційних систем банку, мережевого обладнання та серверів.', category: 'Privileged Access', source: 'NBU Resolution №95 п. 87' },
  { controlCode: 'NBU95-88', title: 'Банк зобов’язаний визначити та запровадити посилені вимоги щодо парольної політики для привілейованих облікових записів (довжина та складність паролів, часто...', description: 'Банк зобов’язаний визначити та запровадити посилені вимоги щодо парольної політики для привілейованих облікових записів (довжина та складність паролів, частота зміни) або застосовувати багатофакторну автентифікацію для таких облікових записів.', category: 'Privileged Access', source: 'NBU Resolution №95 п. 88' },
  { controlCode: 'NBU95-89', title: 'Банк зобов’язаний забезпечити централізоване управління мережею банку (єдине місце управління). Банк має право здійснювати локальне управління мережею банку ...', description: 'Банк зобов’язаний забезпечити централізоване управління мережею банку (єдине місце управління). Банк має право здійснювати локальне управління мережею банку на різних вузлах за умови централізованого управління такими функціями: 1) вибір і монтаж кабельної системи мережі; 2) підбір комутаційного обладнання мережі; 3) підбір обладнання, що підключається до мережі банку, операційних систем, програмного забезпечення інформаційних систем банку, прикладного програмного забезпечення; 4) управління мережевими адресами та ідентифікаторами обладнання і користувачів; 5) розподіл мережі на сегменти.', category: 'Network Security', source: 'NBU Resolution №95 п. 89' },
  { controlCode: 'NBU95-90', title: 'Банк зобов’язаний забезпечити підтримання в актуальному стані документації мережі банку (в електронному та/або паперовому вигляді), документування всіх змін ...', description: 'Банк зобов’язаний забезпечити підтримання в актуальному стані документації мережі банку (в електронному та/або паперовому вигляді), документування всіх змін у конфігурації мережі банку та зберігання попередніх версій документації мережі строком не менше ніж один рік. Документація мережі банку має бути погоджена відповідальною особою за інформаційну безпеку банку та містити: 1) фізичну схему мережі, уключаючи бездротові мережі, що відображає всі з’єднання в мережі; 2) логічну схему мережі, уключаючи бездротові мережі, що відображає всі мережеві пристрої, критично важливі сервери та сервіси; 3) конфігурацію мережевого обладнання, уключаючи бездротові мережі.', category: 'Network Security', source: 'NBU Resolution №95 п. 90' },
  { controlCode: 'NBU95-91', title: 'Банк зобов’язаний задокументувати порядок контролю змін у конфігурації мережі, у якому мають зазначатися вимоги щодо перегляду конфігурації мережі не рідше н...', description: 'Банк зобов’язаний задокументувати порядок контролю змін у конфігурації мережі, у якому мають зазначатися вимоги щодо перегляду конфігурації мережі не рідше ніж один раз на рік з документуванням результатів перегляду.', category: 'Network Security', source: 'NBU Resolution №95 п. 91' },
  { controlCode: 'NBU95-92', title: 'Банк зобов’язаний здійснити розподіл мережі банку на фізичному та/або логічному рівні (сегментацію мережі) і обмежити доступ між сегментами мережі з використ...', description: 'Банк зобов’язаний здійснити розподіл мережі банку на фізичному та/або логічному рівні (сегментацію мережі) і обмежити доступ між сегментами мережі з використанням міжмережевих екранів.', category: 'Network Security', source: 'NBU Resolution №95 п. 92' },
  { controlCode: 'NBU95-93', title: 'Банк зобов’язаний забезпечити ідентифікацію обладнання (наприклад, за ідентифікатором управління доступом до обладнання, MAC адреса), що підключається до мер...', description: 'Банк зобов’язаний забезпечити ідентифікацію обладнання (наприклад, за ідентифікатором управління доступом до обладнання, MAC адреса), що підключається до мережі банку, та вжиття заходів, які унеможливлюють роботу обладнання в мережі без відповідної ідентифікації.', category: 'Network Security', source: 'NBU Resolution №95 п. 93' },
  { controlCode: 'NBU95-94', title: 'Банк зобов’язаний забезпечити програмне відключення портів на активних мережевих пристроях мережі банку, які не використовуються.', description: 'Банк зобов’язаний забезпечити програмне відключення портів на активних мережевих пристроях мережі банку, які не використовуються.', category: 'Network Security', source: 'NBU Resolution №95 п. 94' },
  { controlCode: 'NBU95-95', title: 'Банку забороняється використовувати облікові записи та паролі за замовчуванням на активних мережевих пристроях, які підключені до мережі банку.', description: 'Банку забороняється використовувати облікові записи та паролі за замовчуванням на активних мережевих пристроях, які підключені до мережі банку.', category: 'Network Security', source: 'NBU Resolution №95 п. 95' },
  { controlCode: 'NBU95-96', title: 'Банку забороняється використовувати протокол Інтернету версії 6 (IPv6) у мережі банку.', description: 'Банку забороняється використовувати протокол Інтернету версії 6 (IPv6) у мережі банку.', category: 'Network Security', source: 'NBU Resolution №95 п. 96' },
  { controlCode: 'NBU95-97', title: 'Банку забороняється використовувати версії 1 або 2 простого протоколу керування мережею (Simple network management protocol, SNMP) для управління пристроями ...', description: 'Банку забороняється використовувати версії 1 або 2 простого протоколу керування мережею (Simple network management protocol, SNMP) для управління пристроями в мережі.', category: 'Network Security', source: 'NBU Resolution №95 п. 97' },
  { controlCode: 'NBU95-98', title: 'Банк зобов’язаний забезпечити синхронізацію всіх активних мережевих пристроїв з еталонним джерелом часу банку.', description: 'Банк зобов’язаний забезпечити синхронізацію всіх активних мережевих пристроїв з еталонним джерелом часу банку.', category: 'Network Security', source: 'NBU Resolution №95 п. 98' },
  { controlCode: 'NBU95-99', title: 'Банк зобов’язаний розробити та впровадити заходи безпеки інформації у разі використання бездротових мереж передавання даних (далі – бездротові мережі).', description: 'Банк зобов’язаний розробити та впровадити заходи безпеки інформації у разі використання бездротових мереж передавання даних (далі – бездротові мережі).', category: 'Network Security', source: 'NBU Resolution №95 п. 99' },
  { controlCode: 'NBU95-100', title: 'Банк зобов’язаний розмістити бездротові мережі банку в окремій зоні безпеки мережі банку (сегмент або набір сегментів мережі зі спільним рівнем безпеки) та р...', description: 'Банк зобов’язаний розмістити бездротові мережі банку в окремій зоні безпеки мережі банку (сегмент або набір сегментів мережі зі спільним рівнем безпеки) та розмежувати доступ із зони безпеки бездротових мереж до мережі банку з використанням міжмережевих екранів.', category: 'Network Security', source: 'NBU Resolution №95 п. 100' },
  { controlCode: 'NBU95-101', title: 'Банк зобов’язаний встановити ідентифікатори бездротових мереж (SSID), відмінні від встановлених виробником або інсталятором обладнання за замовчуванням. Банк...', description: 'Банк зобов’язаний встановити ідентифікатори бездротових мереж (SSID), відмінні від встановлених виробником або інсталятором обладнання за замовчуванням. Банк зобов’язаний відключити трансляцію ідентифікаторів бездротових мереж (окрім бездротової мережі, призначеної для гостьових підключень).', category: 'Network Security', source: 'NBU Resolution №95 п. 101' },
  { controlCode: 'NBU95-102', title: 'Банк зобов’язаний забезпечити використання в бездротових мережах банку режиму безпеки WPA2-Enterprise (корпоративний режим у наборі алгоритмів і протоколів W...', description: 'Банк зобов’язаний забезпечити використання в бездротових мережах банку режиму безпеки WPA2-Enterprise (корпоративний режим у наборі алгоритмів і протоколів Wireless protected access версії 2) та використання режиму безпеки WPA2-Personal (персональний режим у наборі алгоритмів і протоколів Wireless protected access версії 2) для реалізації гостьових підключень.', category: 'Network Security', source: 'NBU Resolution №95 п. 102' },
  { controlCode: 'NBU95-103', title: 'Банк зобов’язаний застосовувати такі заходи безпеки інформації для організації віддаленого доступу до інформаційних систем банку: 1) розміщення сервера (серв...', description: 'Банк зобов’язаний застосовувати такі заходи безпеки інформації для організації віддаленого доступу до інформаційних систем банку: 1) розміщення сервера (серверів) віддаленого доступу до інформаційних систем банку в демілітаризованій зоні (DMZ) мережі банку, з обмеженням доступу до нього з публічної мережі за допомогою міжмережевого екрана або пристрою уніфікованого управління загрозами; 2) шифрування каналів зв’язку для доступу до сервера віддаленого доступу до інформаційних систем банку; 3) багатофакторна автентифікація користувачів.', category: 'Network Security', source: 'NBU Resolution №95 п. 103' },
  { controlCode: 'NBU95-104', title: 'Банк зобов’язаний забезпечити розмежування доступу між мережею банку і публічною мережею з використанням міжмережевих екранів та/або пристроїв уніфікованого ...', description: 'Банк зобов’язаний забезпечити розмежування доступу між мережею банку і публічною мережею з використанням міжмережевих екранів та/або пристроїв уніфікованого управління загрозами.', category: 'Network Security', source: 'NBU Resolution №95 п. 104' },
  { controlCode: 'NBU95-105', title: 'Банк зобов’язаний обробляти виявлені атаки або вторгнення до мережі банку в рамках процесу управління інцидентами безпеки інформації. Банк самостійно визнача...', description: 'Банк зобов’язаний обробляти виявлені атаки або вторгнення до мережі банку в рамках процесу управління інцидентами безпеки інформації. Банк самостійно визначає критерії віднесення таких атак або вторгнень до інцидентів безпеки інформації.', category: 'Network Security', source: 'NBU Resolution №95 п. 105' },
  { controlCode: 'NBU95-106', title: 'Банк зобов’язаний забезпечити доступ з публічної мережі до мережі банку виключно із застосуванням захищених з’єднань.', description: 'Банк зобов’язаний забезпечити доступ з публічної мережі до мережі банку виключно із застосуванням захищених з’єднань.', category: 'Network Security', source: 'NBU Resolution №95 п. 106' },
  { controlCode: 'NBU95-107', title: 'Банк зобов’язаний забезпечити розміщення в демілітаризованій зоні мережі банку серверів та обладнання, що забезпечує функціонування сервісів або банківських ...', description: 'Банк зобов’язаний забезпечити розміщення в демілітаризованій зоні мережі банку серверів та обладнання, що забезпечує функціонування сервісів або банківських продуктів, які відкриті для доступу клієнтів з публічної мережі. З’єднання серверів та обладнання, що розміщено в демілітаризованій зоні, з серверами та обладнанням мережі банку захищаються міжмережевим екраном.', category: 'Network Security', source: 'NBU Resolution №95 п. 107' },
  { controlCode: 'NBU95-108', title: 'Банк зобов’язаний виконувати перевірку ефективності заходів щодо захисту периметра мережі банку шляхом виконання періодичних тестів на проникнення.', description: 'Банк зобов’язаний виконувати перевірку ефективності заходів щодо захисту периметра мережі банку шляхом виконання періодичних тестів на проникнення.', category: 'Security Testing', source: 'NBU Resolution №95 п. 108' },
  { controlCode: 'NBU95-109', title: 'Національний банк визначає інформаційні задачі, у яких для забезпечення застосування електронного цифрового підпису обов’язковим є використання послуг електр...', description: 'Національний банк визначає інформаційні задачі, у яких для забезпечення застосування електронного цифрового підпису обов’язковим є використання послуг електронного цифрового підпису від акредитованих центрів сертифікації ключів (далі – акредитовані ЦСК).', category: 'Digital Signature', source: 'NBU Resolution №95 п. 109' },
  { controlCode: 'NBU95-110', title: 'У випадках отримання послуг електронного цифрового підпису від зареєстрованих центрів сертифікації ключів (далі – зареєстровані ЦСК) взаємне визнання електро...', description: 'У випадках отримання послуг електронного цифрового підпису від зареєстрованих центрів сертифікації ключів (далі – зареєстровані ЦСК) взаємне визнання електронного цифрового підпису між учасниками електронної взаємодії визначається договірними засадами. Крім того, у договорі обов’язково мають обумовлюватися права, обов’язки та відповідальність сторін, розподіл ризиків збитків, що можуть бути заподіяні підписувачам, користувачам та третім особам, порядок вирішення спорів у разі їх виникнення.', category: 'Digital Signature', source: 'NBU Resolution №95 п. 110' },
  { controlCode: 'NBU95-111', title: 'Акредитовані ЦСК та зареєстровані ЦСК зобов’язані здійснювати свою діяльність відповідно до регламенту роботи, що визначає організаційно методологічні та тех...', description: 'Акредитовані ЦСК та зареєстровані ЦСК зобов’язані здійснювати свою діяльність відповідно до регламенту роботи, що визначає організаційно методологічні та технологічні умови його діяльності в процесі надання послуг електронного цифрового підпису підписувачам. Регламент роботи ЦСК має бути розроблений та погоджений відповідно до вимог чинного законодавства.', category: 'Digital Signature', source: 'NBU Resolution №95 п. 111' },
  { controlCode: 'NBU95-112', title: 'Банк зобов’язаний розробити та затвердити внутрішні документи, які встановлюють вимоги щодо безпеки інформації, технічного обслуговування, експлуатації факси...', description: 'Банк зобов’язаний розробити та затвердити внутрішні документи, які встановлюють вимоги щодо безпеки інформації, технічного обслуговування, експлуатації факсимільних апаратів, багатофункціональних пристроїв, телефонів та/або телефонних систем та мають містити такі положення щодо: 1) функцій та обов’язків персоналу банку стосовно підключення, технічного обслуговування та експлуатації систем та пристроїв зв’язку; 2) категорій інформації за критерієм конфіденційності, що може передаватися пристроями зв’язку; 3) обов’язковості очищення оперативної та постійної пам’яті факсимільних апаратів і багатофункціональних пристроїв перед передаванням їх третім сторонам або перед виведенням з експлуатації.', category: 'Telecom & Peripherals', source: 'NBU Resolution №95 п. 112' },
  { controlCode: 'NBU95-113', title: 'Банк зобов’язаний створити та підтримувати в актуальному стані перелік факсимільних апаратів і багатофункціональних пристроїв (в електронному або паперовому ...', description: 'Банк зобов’язаний створити та підтримувати в актуальному стані перелік факсимільних апаратів і багатофункціональних пристроїв (в електронному або паперовому вигляді), який містить унікальні ідентифікатори обладнання та місце його розташування.', category: 'Telecom & Peripherals', source: 'NBU Resolution №95 п. 113' },
  { controlCode: 'NBU95-114', title: 'Банк зобов’язаний ознайомити своїх працівників із документами, які встановлюють вимоги щодо безпеки інформації, технічного обслуговування та експлуатації фак...', description: 'Банк зобов’язаний ознайомити своїх працівників із документами, які встановлюють вимоги щодо безпеки інформації, технічного обслуговування та експлуатації факсимільних апаратів, багатофункціональних пристроїв для друку, телефонів та/або телефонних систем.', category: 'Telecom & Peripherals', source: 'NBU Resolution №95 п. 114' },
  { controlCode: 'NBU95-115', title: 'Банк зобов’язаний розміщувати обладнання телефонної мережі (сервери, комутаційне та абонентське обладнання) в окремому сегменті мережі банку, захищеному за д...', description: 'Банк зобов’язаний розміщувати обладнання телефонної мережі (сервери, комутаційне та абонентське обладнання) в окремому сегменті мережі банку, захищеному за допомогою міжмережевого екрана.', category: 'Telecom & Peripherals', source: 'NBU Resolution №95 п. 115' },
  { controlCode: 'NBU95-116', title: 'Банк зобов’язаний запровадити такі заходи безпеки в разі використання телефонного зв’язку на основі протоколу Інтернет (IP-телефонії): 1) активувати вбудован...', description: 'Банк зобов’язаний запровадити такі заходи безпеки в разі використання телефонного зв’язку на основі протоколу Інтернет (IP-телефонії): 1) активувати вбудовані алгоритми шифрування трафіку між шлюзами, які забезпечують роботу телефонної системи банку, або між шлюзом та кінцевим абонентським обладнанням (телефоном); 2) здійснювати розподіл унікальних ідентифікаторів мережевого рівня (IP-адрес) у телефонній мережі банку відповідно до стандарту RFC 1918 “Розподіл адрес у приватних IP-мережах”. використання електронної пошти, який має містити положення щодо:', category: 'Telecom & Peripherals', source: 'NBU Resolution №95 п. 116' },
  { controlCode: 'NBU95-117', title: 'Банк зобов’язаний розробити та затвердити документ щодо 1) обмежень під час пересилання інформації банку; пошти; 2) категорії інформації, яка може надсилатис...', description: 'Банк зобов’язаний розробити та затвердити документ щодо 1) обмежень під час пересилання інформації банку; пошти; 2) категорії інформації, яка може надсилатись засобами електронної пов’язані з виконанням функціональних обов’язків персоналом банку. 3) обмежень використання сторонніх сервісів електронної пошти, які не інформації для сервера електронної пошти,', category: 'Email Security', source: 'NBU Resolution №95 п. 117' },
  { controlCode: 'NBU95-118', title: 'Банк зобов’язаний розробити та впровадити заходи безпеки які включають: 1) додаткові заходи безпеки операційної системи, на якій встановлено сервер застосува...', description: 'Банк зобов’язаний розробити та впровадити заходи безпеки які включають: 1) додаткові заходи безпеки операційної системи, на якій встановлено сервер застосувань електронної пошти; 2)заходи безпеки сервера застосувань електронної пошти; 3) налаштування правил доступу до сервера електронної пошти.', category: 'Email Security', source: 'NBU Resolution №95 п. 118' },
  { controlCode: 'NBU95-119', title: 'Банк зобов’язаний забезпечити перевірку програмними або апаратними засобами захисту всіх повідомлень, що обробляються сервером застосувань електронної пошти,...', description: 'Банк зобов’язаний забезпечити перевірку програмними або апаратними засобами захисту всіх повідомлень, що обробляються сервером застосувань електронної пошти, на наявність зловмисного коду.', category: 'Email Security', source: 'NBU Resolution №95 п. 119' },
  { controlCode: 'NBU95-120', title: 'Банк зобов’язаний впровадити періодичне тестування захищеності та перегляд налаштувань параметрів безпеки операційної системи сервера застосувань електронної...', description: 'Банк зобов’язаний впровадити періодичне тестування захищеності та перегляд налаштувань параметрів безпеки операційної системи сервера застосувань електронної пошти та безпосередньо сервера застосувань електронної пошти.', category: 'Email Security', source: 'NBU Resolution №95 п. 120' },
  { controlCode: 'NBU95-121', title: 'Банк зобов’язаний розміщувати сервер застосувань електронної пошти на окремому фізичному або віртуальному сервері.', description: 'Банк зобов’язаний розміщувати сервер застосувань електронної пошти на окремому фізичному або віртуальному сервері.', category: 'Email Security', source: 'NBU Resolution №95 п. 121' },
  { controlCode: 'NBU95-122', title: 'У разі використання віддаленого доступу до сервера застосувань електронної пошти банк зобов’язаний запровадити такі заходи безпеки інформації: 1) сервер має ...', description: 'У разі використання віддаленого доступу до сервера застосувань електронної пошти банк зобов’язаний запровадити такі заходи безпеки інформації: 1) сервер має бути розміщений в демілітаризованій зоні мережі банку з обмеженням доступу до нього з публічної мережі за допомогою міжмережевого екрана або пристрою уніфікованого управління загрозами; 2) доступ до сервера електронної пошти має надаватись лише шифрованими каналами зв’язку.', category: 'Email Security', source: 'NBU Resolution №95 п. 122' },
  { controlCode: 'NBU95-123', title: 'Банк зобов’язаний запровадити такі заходи безпеки інформації для сервера електронної пошти: 1) використовувати міжмережевий екран операційної системи сервера...', description: 'Банк зобов’язаний запровадити такі заходи безпеки інформації для сервера електронної пошти: 1) використовувати міжмережевий екран операційної системи сервера електронної пошти для обмеження доступу до сервера; 2) заблокувати отримання вхідних повідомлень від серверів мережі Інтернет, що розсилають спам; 3) упровадити процес постійного моніторингу вразливостей сервера застосувань електронної пошти та клієнтського програмного забезпечення доступу до сервера застосувань електронної пошти, забезпечити встановлення відповідних оновлень, що усувають виявлені вразливості.', category: 'Email Security', source: 'NBU Resolution №95 п. 123' },
  { controlCode: 'NBU95-124', title: 'Банк зобов’язаний визначити та задокументувати вимоги безпеки інформації для інформаційних систем банку під час їх розроблення, модернізації (у тому числі їх...', description: 'Банк зобов’язаний визначити та задокументувати вимоги безпеки інформації для інформаційних систем банку під час їх розроблення, модернізації (у тому числі їх компонентів) або в разі придбання.', category: 'SDLC & System Lifecycle', source: 'NBU Resolution №95 п. 124' },
  { controlCode: 'NBU95-125', title: 'На стадії розроблення і тестування інформаційних систем банку та/або їх компонентів банк зобов’язаний використовувати тестову програмно апаратну платформу, я...', description: 'На стадії розроблення і тестування інформаційних систем банку та/або їх компонентів банк зобов’язаний використовувати тестову програмно апаратну платформу, яка підключена до окремого (тестового) виділеного сегмента мережі банку. Як тестові дані банк має право використовувати виключно знеособлені дані.', category: 'SDLC & System Lifecycle', source: 'NBU Resolution №95 п. 125' },
  { controlCode: 'NBU95-126', title: 'Банк зобов’язаний розробити документацію для інформаційних систем банку та/або їх компонентів з обов’язковим описом реалізованих в інформаційних системах бан...', description: 'Банк зобов’язаний розробити документацію для інформаційних систем банку та/або їх компонентів з обов’язковим описом реалізованих в інформаційних системах банку організаційних та технічних заходів безпеки інформації, якщо така документація не надана розробником інформаційних систем банку.', category: 'SDLC & System Lifecycle', source: 'NBU Resolution №95 п. 126' },
  { controlCode: 'NBU95-127', title: 'Банк зобов’язаний на стадії експлуатації інформаційних систем задокументувати положення щодо: 1) контролю функціонування реалізованих в інформаційних система...', description: 'Банк зобов’язаний на стадії експлуатації інформаційних систем задокументувати положення щодо: 1) контролю функціонування реалізованих в інформаційних системах банку заходів безпеки інформації, уключаючи контроль реалізації організаційних заходів та контроль складу і параметрів налагодження технічних засобів безпеки інформації; 2) контролю вразливостей в обладнанні та програмному забезпеченні інформаційних систем банку; 3) контролю конфігурації програмного забезпечення інформаційних систем банку; 4) відновлення всіх реалізованих заходів щодо забезпечення безпеки інформації в інформаційних системах банку після збоїв у роботі внаслідок інцидентів безпеки інформації.', category: 'SDLC & System Lifecycle', source: 'NBU Resolution №95 п. 127' },
  { controlCode: 'NBU95-128', title: 'Банк зобов’язаний визначити функції та обов’язки, пов’язані з експлуатацією інформаційних систем і впроваджених в них заходів безпеки інформації, уключаючи в...', description: 'Банк зобов’язаний визначити функції та обов’язки, пов’язані з експлуатацією інформаційних систем і впроваджених в них заходів безпеки інформації, уключаючи внесення змін до параметрів їх налаштування.', category: 'SDLC & System Lifecycle', source: 'NBU Resolution №95 п. 128' },
  { controlCode: 'NBU95-129', title: 'Банк зобов’язаний задокументувати та впровадити порядок виведення з експлуатації обладнання інформаційних систем банку, який має містити опис процесу видален...', description: 'Банк зобов’язаний задокументувати та впровадити порядок виведення з експлуатації обладнання інформаційних систем банку, який має містити опис процесу видалення інформації з таких систем, використовуючи алгоритми та/або методи, що забезпечать неможливість її відновлення.', category: 'SDLC & System Lifecycle', source: 'NBU Resolution №95 п. 129' },
  { controlCode: 'NBU95-130', title: 'Банк зобов’язаний упровадити процес управління інцидентами безпеки інформації та розробити і затвердити документи, які містять описи дій стосовно: 1) виявлен...', description: 'Банк зобов’язаний упровадити процес управління інцидентами безпеки інформації та розробити і затвердити документи, які містять описи дій стосовно: 1) виявлення інцидентів; 2) інформування про інциденти, у тому числі відповідальної особи за інформаційну безпеку, підрозділу з безпеки інформації та працівників банку; 3) класифікації інцидентів та оцінки негативного впливу (збитку), нанесеного банку інцидентом; 4) реагування на інциденти; 5) аналізу причин, що призвели до інцидентів та оцінки результатів реагування на інциденти; 6) зберігання інформації щодо інцидентів, аналізу інцидентів та результатів реагування на інциденти.', category: 'Incident Management', source: 'NBU Resolution №95 п. 130' },
  { controlCode: 'NBU95-131', title: 'Банк зобов’язаний визначити в посадових інструкціях працівників банку або організаційно-розпорядчих документах банку особисті функції та обов’язки з виявленн...', description: 'Банк зобов’язаний визначити в посадових інструкціях працівників банку або організаційно-розпорядчих документах банку особисті функції та обов’язки з виявлення, класифікації, реагування і аналізу інцидентів безпеки інформації.', category: 'Incident Management', source: 'NBU Resolution №95 п. 131' },
  { controlCode: 'NBU95-132', title: 'Банк зобов’язаний забезпечити документування інформації щодо інцидентів безпеки інформації та її зберігання не менше ніж один рік. V. Додаткові заходи безпек...', description: 'Банк зобов’язаний забезпечити документування інформації щодо інцидентів безпеки інформації та її зберігання не менше ніж один рік. V. Додаткові заходи безпеки інформації', category: 'Incident Management', source: 'NBU Resolution №95 п. 132' },
  { controlCode: 'NBU95-133', title: 'Банку забороняється використовувати радіотелефони та/або радіоподовжувачі телефонної лінії без активованих у них алгоритмів шифрування сигналу, який передаєт...', description: 'Банку забороняється використовувати радіотелефони та/або радіоподовжувачі телефонної лінії без активованих у них алгоритмів шифрування сигналу, який передається радіоканалом.', category: 'V. Additional Measures', source: 'NBU Resolution №95 п. 133' },
  { controlCode: 'NBU95-134', title: 'Банк зобов’язаний створити та підтримувати в актуальному стані (в електронному або паперовому вигляді) перелік змінних носіїв інформації банку.', description: 'Банк зобов’язаний створити та підтримувати в актуальному стані (в електронному або паперовому вигляді) перелік змінних носіїв інформації банку.', category: 'V. Additional Measures', source: 'NBU Resolution №95 п. 134' },
  { controlCode: 'NBU95-135', title: 'Банк зобов’язаний використовувати виключно ідентифіковані змінні носії інформації в інформаційних системах банку.', description: 'Банк зобов’язаний використовувати виключно ідентифіковані змінні носії інформації в інформаційних системах банку.', category: 'V. Additional Measures', source: 'NBU Resolution №95 п. 135' },
  { controlCode: 'NBU95-136', title: 'Банк зобов’язаний автоматизувати процес контролю за використанням змінних носіїв інформації в інформаційних системах банку. Банк має право самостійно визнача...', description: 'Банк зобов’язаний автоматизувати процес контролю за використанням змінних носіїв інформації в інформаційних системах банку. Банк має право самостійно визначати методи та засоби (технології) автоматизації такого процесу.', category: 'V. Additional Measures', source: 'NBU Resolution №95 п. 136' },
  { controlCode: 'NBU95-137', title: 'Банк зобов’язаний використовувати централізовані системи управління обліковими записами.', description: 'Банк зобов’язаний використовувати централізовані системи управління обліковими записами.', category: 'V. Additional Measures', source: 'NBU Resolution №95 п. 137' },
  { controlCode: 'NBU95-138', title: 'Банк зобов’язаний використовувати інструменти централізованого моніторингу та застосування оновлень безпеки для операційних систем.', description: 'Банк зобов’язаний використовувати інструменти централізованого моніторингу та застосування оновлень безпеки для операційних систем.', category: 'V. Additional Measures', source: 'NBU Resolution №95 п. 138' },
  { controlCode: 'NBU95-139', title: 'Банк зобов’язаний автоматизувати процес управління інцидентами безпеки інформації. Банк має право самостійно визначати методи та засоби (технології) автомати...', description: 'Банк зобов’язаний автоматизувати процес управління інцидентами безпеки інформації. Банк має право самостійно визначати методи та засоби (технології) автоматизації такого процесу.', category: 'V. Additional Measures', source: 'NBU Resolution №95 п. 139' },
  { controlCode: 'NBU95-140', title: 'Банк зобов’язаний використовувати досконалу пряму секретність (Perfect forward secrecy, PFS) для з’єднань на основі протоколу захисту на транспортному рівні.', description: 'Банк зобов’язаний використовувати досконалу пряму секретність (Perfect forward secrecy, PFS) для з’єднань на основі протоколу захисту на транспортному рівні.', category: 'V. Additional Measures', source: 'NBU Resolution №95 п. 140' },
  { controlCode: 'NBU95-141', title: 'Банк зобов’язаний здійснювати маркування та документування елементів СКС відповідно до рекомендацій міжнародного стандарту ANSI/TIA/EIA-606.', description: 'Банк зобов’язаний здійснювати маркування та документування елементів СКС відповідно до рекомендацій міжнародного стандарту ANSI/TIA/EIA-606.', category: 'V. Additional Measures', source: 'NBU Resolution №95 п. 141' },
  { controlCode: 'NBU95-142', title: 'Банк зобов’язаний застосовувати комбінацію програмних та програмно-апаратних засобів захисту від зловмисного коду (наприклад, використання програмних антивір...', description: 'Банк зобов’язаний застосовувати комбінацію програмних та програмно-апаратних засобів захисту від зловмисного коду (наприклад, використання програмних антивірусних засобів на робочих станціях і серверах та використання систем запобігання несанкціонованому доступу до мережі на зовнішньому периметрі мережі банку).', category: 'V. Additional Measures', source: 'NBU Resolution №95 п. 142' },
  { controlCode: 'NBU95-143', title: 'Банк зобов’язаний використовувати стандарти, документи та настанови відкритого проекту захисту веб-додатків “Open web application security project” (OWASP) д...', description: 'Банк зобов’язаний використовувати стандарти, документи та настанови відкритого проекту захисту веб-додатків “Open web application security project” (OWASP) для розроблення безпечних веб-додатків.', category: 'V. Additional Measures', source: 'NBU Resolution №95 п. 143' },
  { controlCode: 'NBU95-144', title: 'Банк зобов’язаний забезпечити шифрування каналів передавання даних між серверами СУБД і серверами застосувань або шифрування даних, що передаються між сервер...', description: 'Банк зобов’язаний забезпечити шифрування каналів передавання даних між серверами СУБД і серверами застосувань або шифрування даних, що передаються між серверами СУБД і серверами застосувань банку.', category: 'V. Additional Measures', source: 'NBU Resolution №95 п. 144' },
  { controlCode: 'NBU95-145', title: 'Банк зобов’язаний здійснити функціональний розподіл серверів банку на мережевому рівні та забезпечити між ними мінімально необхідний зв’язок, що дозволить пр...', description: 'Банк зобов’язаний здійснити функціональний розподіл серверів банку на мережевому рівні та забезпечити між ними мінімально необхідний зв’язок, що дозволить працювати серверам незалежно один від одного.', category: 'V. Additional Measures', source: 'NBU Resolution №95 п. 145' },
  { controlCode: 'NBU95-146', title: 'Банк зобов’язаний використовувати проміжний сервер для виконання функцій адміністрування чи супроводження інформаційних систем банку, мережевого обладнання т...', description: 'Банк зобов’язаний використовувати проміжний сервер для виконання функцій адміністрування чи супроводження інформаційних систем банку, мережевого обладнання та серверів. Підключення до такого сервера має здійснюватися з використанням непривілейованих облікових записів, а підключення з проміжного сервера до інформаційних систем банку, мережевого обладнання та серверів – із використанням привілейованих облікових записів. Банк має право застосовувати альтернативні технології щодо управління та контролю доступом, які виключають прямий доступ привілейованих користувачів (адміністраторів) до інформаційних систем банку, мережевого обладнання та серверів.', category: 'V. Additional Measures', source: 'NBU Resolution №95 п. 146' },
  { controlCode: 'NBU95-147', title: 'Банк зобов’язаний використовувати механізми багатофакторної автентифікації під час надання доступу до САБ.', description: 'Банк зобов’язаний використовувати механізми багатофакторної автентифікації під час надання доступу до САБ.', category: 'V. Additional Measures', source: 'NBU Resolution №95 п. 147' },
  { controlCode: 'NBU95-148', title: 'Банк зобов’язаний упровадити системи виявлення несанкціонованого доступу до мережі (Intrusion detection system, IDS) та системи запобігання несанкціонованому...', description: 'Банк зобов’язаний упровадити системи виявлення несанкціонованого доступу до мережі (Intrusion detection system, IDS) та системи запобігання несанкціонованому доступу до мережі (Intrusion prevention system, IPS) для захисту периметра мережі банку.', category: 'V. Additional Measures', source: 'NBU Resolution №95 п. 148' },
  { controlCode: 'NBU95-149', title: 'Банк зобов’язаний застосувати заходи безпеки для захисту від атак на відмову в обслуговуванні та/або розподілених атак на відмову в обслуговуванні (DoS/DDoS-...', description: 'Банк зобов’язаний застосувати заходи безпеки для захисту від атак на відмову в обслуговуванні та/або розподілених атак на відмову в обслуговуванні (DoS/DDoS-атак) на зовнішньому периметрі мережі банку. Банк самостійно визначає методи та засоби (технології) захисту від такого типу атак.', category: 'V. Additional Measures', source: 'NBU Resolution №95 п. 149' },
  { controlCode: 'NBU95-150', title: 'Банк зобов’язаний використовувати сертифікати відкритих ключів, отримані в акредитованих/зареєстрованих ЦСК для ідентифікації та автентифікації, забезпечення...', description: 'Банк зобов’язаний використовувати сертифікати відкритих ключів, отримані в акредитованих/зареєстрованих ЦСК для ідентифікації та автентифікації, забезпечення конфіденційності інформації під час інформаційного обміну між інформаційними системами банку та Національного банку.', category: 'V. Additional Measures', source: 'NBU Resolution №95 п. 150' },
];
